/// <summary>
/// METInventItemOrderSetupUpdatePalletQuantitiesService
/// Service class responsible for executing batch updates of pallet-related
/// quantities (CartonPerPallet, PalletLayerQty, PalletQty) in Default Order Settings.
/// Handles initialization, task contract binding, and processing of eligible
/// item order setup records into the update queue.
/// </summary>
class METInventItemOrderSetupUpdatePalletQuantitiesService extends METSysOperationService
{
    private guid topPickingProcessId;

}

Method.Source:
/// <summary>
/// Returns the name of the task service class used for pallet quantity updates.
/// </summary>
/// <returns>Task service class name.</returns>
protected str getTaskServiceClass()
{
    return classStr(METInventItemOrderSetupUpdatePalletQuantitiesTaskService);
}

/// <summary>
/// Returns the method name of the task service class to be executed.
/// </summary>
/// <returns>Task service class method name.</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METInventItemOrderSetupUpdatePalletQuantitiesTaskService, process);
}

// <summary>
/// Returns the caption associated with the pallet quantity update task service.
/// </summary>
/// <returns>Task service caption string.</returns>
protected str getTaskServiceCaption()
{
    return "@MET:UpdatePalletQty";
}

/// <summary>
/// Entry point for processing pallet quantity updates using the provided contract.
/// </summary>
/// <param name="_contract">Update data contract.</param>
public void process(METInventItemOrderSetupUpdatePalletQuantitiesContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Initializes global variables and triggers pallet quantity updates based on the contract query.
/// </summary>
public void initialise()
{
    super();

    METInventItemOrderSetupUpdatePalletQuantitiesContract contract = dataContract as METInventItemOrderSetupUpdatePalletQuantitiesContract;
    Query query = contract.getQuery();

    this.processUpdatePalletQty(query);
}

/// <summary>
/// Initializes the task data contract with process identifiers.
/// </summary>
/// <param name="_taskDataContract">Task data contract instance.</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METInventItemOrderSetupUpdatePalletQuantitiesContract contract = _taskDataContract as METInventItemOrderSetupUpdatePalletQuantitiesContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides a new instance of the pallet quantity update task data contract.
/// </summary>
/// <returns>Task data contract object.</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METInventItemOrderSetupUpdatePalletQuantitiesContract();
}

/// <summary>
/// Executes pallet quantity updates by iterating through eligible Item Order Setup records
/// from the query and adding them to the update queue with retry handling for conflicts.
/// </summary>
/// <param name="_query">Query object defining eligible Item Order Setup records.</param>
void processUpdatePalletQty(Query _query)
{
    #OCCRetryCount

    METInventItemOrderSetupQueue::cleanUpCPIRepricingQueue();
    RecordInsertList cpiRepricingQueueList = new RecordInsertList(tableNum(METInventItemOrderSetupQueue));
    QueryRun queryRun = new QueryRun(_query);

    topPickingProcessId = newGuid();

    while (queryRun.next())
    {
        try
        {
            METInventItemOrderSetup inventitemOrderSetup = queryRun.get(tableNum(METInventItemOrderSetup));
            this.addToUpdatePalletQtyQueueList(cpiRepricingQueueList, inventitemOrderSetup.ItemId, inventitemOrderSetup.SiteId);
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            // Catch errors so processing can continue
            curext();
        }
    }

    this.insertIntoTopPickingQueue(cpiRepricingQueueList);
}

/// <summary>
/// Adds an Item Order Setup record to the pallet quantity update queue list.
/// </summary>
/// <param name="_updatePalletQtyQueueList">RecordInsertList for pallet quantity update queue.</param>
/// <param name="_itemId">Item identifier.</param>
/// <param name="_siteId">Site identifier.</param>
private void addToUpdatePalletQtyQueueList(RecordInsertList _updatePalletQtyQueueList, ItemId _itemId, InventSiteId _siteId)
{
    METInventItemOrderSetupQueue postRecord;
    postRecord.ProcessId = this.topPickingProcessId;
    postRecord.ItemId = _itemId;
    postRecord.SiteId = _siteId;

    _updatePalletQtyQueueList.add(postRecord);
}

/// <summary>
/// Performs bulk insert of Item Order Setup records into the pallet quantity update queue table.
/// </summary>
/// <param name="_updatePalletQtyQueueList">RecordInsertList containing Item Order Setup records to insert.</param>
private void insertIntoTopPickingQueue(RecordInsertList _updatePalletQtyQueueList)
{
    _updatePalletQtyQueueList.insertDatabase();
}
